/**
 * @name Command injection in HTTP client
 * @description Using os.system, subprocess, or similar with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // System command execution sinks using API graphs
    exists(API::CallNode call |
      // os.system
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.call
      call = API::moduleImport("subprocess").getMember("call").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.run
      call = API::moduleImport("subprocess").getMember("run").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.Popen
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // os.popen
      call = API::moduleImport("os").getMember("popen").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description File system access with untrusted input can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access sinks using API graphs
    exists(API::CallNode call |
      // open() builtin
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // os.open
      call = API::moduleImport("os").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // os.path operations that could be dangerous
      call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "realpath"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name HTTP header injection (CRLF injection)
 * @description Untrusted input in HTTP headers can lead to header injection attacks
 * @kind path-problem
 * @problem.severity high
 * @id py/http-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for HTTP header setting operations
    exists(API::CallNode call |
      // Common HTTP header setting patterns
      call = API::moduleImport("http").getMember("client").getMember("HTTPConnection").getMember("request").getACall() and
      sink = call.getArg(3)  // headers argument
    ) or
    exists(API::CallNode call |
      // urllib request with headers
      call = API::moduleImport("urllib").getMember("request").getMember("Request").getACall() and
      sink = call.getArg(2)  // headers argument
    ) or
    exists(API::CallNode call |
      // Direct header assignment to connection objects - putheader method
      call = API::moduleImport("http").getMember("client").getMember("HTTPConnection").getMember("putheader").getACall() and
      sink = call.getArg(1)  // header value argument
    ) or
    exists(API::CallNode call |
      // requests library headers
      call = API::moduleImport("requests").getMember("get").getACall() and
      sink = call.getArg(1)  // headers argument (kwargs)
    ) or
    exists(API::CallNode call |
      // requests library post with headers
      call = API::moduleImport("requests").getMember("post").getACall() and
      sink = call.getArg(2)  // headers argument (kwargs)
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTTP header injection from $@.", source.getNode(), "user input"
